import csv, sqlite3

with open("exports/user_export_exp-6421.csv", newline="", encoding="utf-8") as fh:
    rows = list(csv.reader(fh))
data = [tuple(r) for r in rows[1:]]

con = sqlite3.connect("file:recovery/snapshot.db?mode=ro", uri=True)
db_rows = [tuple(r) for r in con.execute("SELECT uid, name, email, department, plan FROM users ORDER BY uid")]
con.close()

csv_by_uid = {int(r[0]): r for r in data}
db_by_uid = {int(r[0]): r for r in db_rows}

print("uid only in CSV:", sorted(set(csv_by_uid) - set(db_by_uid)))
print("uid only in DB :", sorted(set(db_by_uid) - set(csv_by_uid)))

mismatches = 0
for uid in sorted(set(csv_by_uid) & set(db_by_uid)):
    if csv_by_uid[uid] != db_by_uid[uid]:
        mismatches += 1
        if mismatches <= 20:
            print("DIFF uid=%d\n  csv: %r\n  db : %r" % (uid, csv_by_uid[uid], db_by_uid[uid]))
print("total mismatched rows:", mismatches)
EOF"}
